+            }
+            checkInvariant(bucket);
+            return;
+        }
+        // Gathering mode
+        long requiredSize = common.requiredSize(rootIndex);
+        if (values.size() < requiredSize) {
+            grow(requiredSize);
+        }
+        int next = getNextGatherOffset(rootIndex);
+        common.assertValidNextOffset(next);
