+    @Override
+    public final void close() {
+        Releasables.close(() -> {
+            for (int i = 0; i < values.size(); i++) {
+                BreakingBytesRefBuilder bytes = values.get(i);
+                if (bytes != null) {
+                    bytes.close();
+                }
+            }
+        }, values, common);
+    }
